      "content": "{\r\n  \"name\": \"browserpaw\",\r\n  \"version\": \"4.1.2\",\r\n  \"description\": \"BrowserPaw - High-efficiency Chrome browser automation MCP server and AI agent skill\",\r\n  \"private\": true,\r\n  \"author\": \"hangye\",\r\n  \"repository\": {\r\n    \"type\": \"git\",\r\n    \"url\": \"https://github.com/GoldenLoaf24h/browserpaw.git\"\r\n  },\r\n  \"homepage\": \"https://github.com/GoldenLoaf24h/browserpaw\",\r\n  \"bugs\": {\r\n    \"url\": \"https://github.com/GoldenLoaf24h/browserpaw/issues\"\r\n  },\r\n  \"type\": \"module\",\r\n  \"packageManager\": \"pnpm@12.6.0\",\r\n  \"engines\": {\r\n    \"node\": \">=22.6.0\"\r\n  },\r\n  \"scripts\": {\r\n    \"verify\": \"node scripts/verify.mjs\",\r\n    \"verify:docs\": \"node scripts/validate-docs.mjs\",\r\n    \"build:deploy\": \"pnpm build && node scripts/extension-artifacts.mjs --deploy\",\r\n    \"verify:delivery\": \"node scripts/extension-artifacts.mjs --check-deployment\",\r\n    \"build:shared\": \"pnpm --filter chrome-mcp-shared build\",\r\n    \"build:native\": \"pnpm --filter mcp-chrome-bridge build\",\r\n    \"build:extension\": \"pnpm --filter chrome-mcp-server build && node scripts/sync-extension-dist.mjs\",\r\n    \"build\": \"pnpm -r --filter=\\\"!browserpaw\\\" run build && node scripts/sync-extension-dist.mjs\",\r\n    \"dev:shared\": \"pnpm --filter chrome-mcp-shared dev\",\r\n    \"dev:native\": \"pnpm --filter mcp-chrome-bridge dev\",\r\n    \"dev:extension\": \"pnpm --filter chrome-mcp-server dev\",\r\n    \"dev\": \"pnpm --filter chrome-mcp-shared build && pnpm -r --parallel dev\",\r\n    \"test\": \"node --experimental-strip-types test/e2e/runner.ts\",\r\n    \"test:e2e\": \"node --experimental-strip-types test/e2e/runner.ts\",\r\n    \"lint\": \"eslint scripts bin --max-warnings=0 && pnpm -r lint\",\r\n    \"lint:fix\": \"pnpm -r lint:fix\",\r\n    \"format\": \"pnpm -r format\",\r\n    \"clean:dist\": \"node scripts/clean.js dist\",\r\n    \"clean:modules\": \"node scripts/clean.js modules\",\r\n    \"clean\": \"node scripts/clean.js all\",\r\n    \"typecheck\": \"pnpm -r --filter=\\\"!browserpaw\\\" exec tsc --noEmit\",\r\n    \"prepare\": \"husky\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@commitlint/cli\": \"^19.8.1\",\r\n    \"@commitlint/config-conventional\": \"^19.8.1\",\r\n    \"@eslint/js\": \"^9.25.1\",\r\n    \"@typescript-eslint/eslint-plugin\": \"^8.32.0\",\r\n    \"@typescript-eslint/parser\": \"^8.32.0\",\r\n    \"eslint\": \"^9.26.0\",\r\n    \"eslint-config-prettier\": \"^10.1.5\",\r\n    \"eslint-plugin-vue\": \"^10.0.0\",\r\n    \"globals\": \"^16.1.0\",\r\n    \"husky\": \"^9.1.7\",\r\n    \"lint-staged\": \"^15.5.1\",\r\n    \"prettier\": \"^3.5.3\",\r\n    \"typescript\": \"^5.8.3\",\r\n    \"typescript-eslint\": \"^8.32.0\",\r\n    \"vue-eslint-parser\": \"^10.1.3\"\r\n  },\r\n  \"lint-staged\": {\r\n    \"**/*.{js,jsx,ts,tsx,vue}\": [\r\n      \"eslint --fix\",\r\n      \"prettier --write\"\r\n    ],\r\n    \"**/*.{json,md,yaml,html,css}\": [\r\n      \"prettier --write\"\r\n    ]\r\n  },\r\n  \"license\": \"AGPL-3.0-or-later\",\r\n  \"bin\": {\r\n    \"browserpaw\": \"./bin/browserpaw.cjs\"\r\n  }\r\n}\r\n"
